const app=document.querySelector('#app');
const navItems=[['dashboard','◫','Dashboard','Tasks, updates and progress'],['tasks','☑','Tasks','Assigned work and daily history'],['messages','✉','Messages','Send notes to CEO or teammates'],['analytics','▥','Analytics','Workload and completion progress'],['employees','♧','Team','Team profiles and activity'],['help','?','Help','Help with Mitra Work'],['settings','⚙','Settings','Edit your profile'],['about','ⓘ','About Mitra Work','Project information']];
let me=null,searchTerm='',cache={};
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initials=n=>String(n||'?').split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();const avatarMarkup=(name,size='')=>me?.photo?`<img class="avatar avatar-photo ${size}" src="${me.photo}" alt="${esc(name)}">`:`<span class="avatar ${size}">${initials(name)}</span>`;
async function api(path,opt={}){const res=await fetch('/api'+path,{...opt,signal:opt.signal||AbortSignal.timeout(12000),headers:{'content-type':'application/json',...(opt.headers||{})}});let data={};try{data=await res.json()}catch{}if(!res.ok)throw Error(data.error||'Request failed.');return data;}
function toast(msg,error=false){const t=document.createElement('div');t.className='toast'+(error?' error':'');t.textContent=msg;document.body.append(t);setTimeout(()=>t.remove(),3300)}
function goto(path){history.pushState({},'',path);searchTerm='';render();}
window.addEventListener('popstate',render);
function logo(){return `<div class="brand"><span class="brand-mark">M</span><span>Mitra <b>Work</b></span></div>`}
function pageKey(){return location.pathname.split('/').filter(Boolean)[0]||'home'}
async function render(){const key=pageKey();if(['login','ceo-login','register','setup'].includes(key)){authPage(key);return;}try{const r=await api('/me');me=r.user;}catch{me=null;}if(!me){if(key==='home'){landing();return;}goto('/');return;}if(['home','login','ceo-login','register','setup'].includes(key)){goto('/dashboard');return;}const allowed=navItems.some(x=>x[0]===key)||key==='settings';if(!allowed){goto('/dashboard');return;}if(key==='employees'&&!['ceo','general_manager','manager','team_leader'].includes(me.role)){toast('Employee management requires administrator access.',true);goto('/dashboard');return;}await shell(key);}
function landing(){app.innerHTML=`<div class="login-page"><section class="login-art">${logo()}<div class="eyebrow" style="color:#c7baff;margin-top:auto">ONE TEAM · ONE WORKSPACE</div><h1>Bring your team closer.<br>Move work forward.</h1><p>One place for assigned work, daily updates, and team communication.</p><div class="feature-pills"><span>☑ Task updates</span><span>✉ Team messages</span><span>✦ Team productivity</span></div></section><section class="login-side"><div class="login-card"><div class="brand" style="padding:0 0 26px;color:var(--ink)"><span class="brand-mark">M</span><span>Mitra <b>Work</b></span></div><h2>Welcome to Mitra Work</h2><p>Choose how you would like to continue.</p><button class="primary" onclick="goto('/login')">Employee Login</button><button class="secondary" style="width:100%;margin-top:10px" onclick="goto('/ceo-login')">CEO Login</button><div class="auth-bottom">New to Mitra Work? <a href="/register" onclick="event.preventDefault();goto('/register')">Create an account</a></div><div id="setup-link" class="auth-bottom"></div></div></section></div>`;api('/setup').then(x=>{if(x.setupNeeded)document.querySelector('#setup-link').innerHTML=`<a href="/setup" onclick="event.preventDefault();goto('/setup')">Set up your workspace →</a>`}).catch(()=>{});}
function authPage(key){if(key==='setup'){api('/setup').then(s=>{if(!s.setupNeeded)goto('/login')}).catch(()=>{});}const setup=key==='setup',register=key==='register',ceo=key==='ceo-login';const title=setup?'Create your workspace':register?'Create an employee account':ceo?'CEO sign in':'Employee sign in';const desc=setup?'Set up the first administrator account.':register?'Choose your work area and create your employee account.':'Sign in to continue to your workspace.';app.innerHTML=`<div class="login-page"><section class="login-art">${logo()}<div class="eyebrow" style="color:#c7baff;margin-top:auto">MITRA WORKSPACE</div><h1>${setup?'Make team work visible.':'One team. One workspace.'}</h1><p>Keep assigned tasks, daily updates, and team priorities in one place.</p><div class="feature-pills"><span>☑ Track assigned work</span><span>✉ Message your team</span></div></section><section class="login-side"><form class="login-card" id="auth-form"><div class="eyebrow">${ceo?'EXECUTIVE ACCESS':setup?'WORKSPACE SETUP':'MITRA WORK'}</div><h2 style="margin-top:8px">${title}</h2><p>${desc}</p><div id="auth-error"></div>${setup||register?`<div class="field"><label>Full name</label><input name="name" required autocomplete="name" placeholder="Your name"></div>`:''}${register?`<div class="field"><label>Work area</label><select name="department" required><option value="">Select your work area</option>${['Frontend','Backend','Full-stack','UI/UX Design','QA / Testing','DevOps / Cloud','Data / Analytics','Sales','Marketing','Customer Support','Operations','HR','Finance','Other'].map(x=>`<option>${x}</option>`).join('')}</select></div>`:''}<div class="field"><label>Email address</label><input name="email" type="email" required autocomplete="email" placeholder="you@company.com"></div><div class="field"><label>Password</label><input name="password" type="password" required minlength="${setup?12:register?10:1}" autocomplete="${register||setup?'new-password':'current-password'}" placeholder="${setup?'At least 12 characters':'Enter your password'}"></div>${!setup&&!register?`<div class="login-links"><label><input type="checkbox" name="remember" checked> Remember me</label><a href="#" id="forgot-link">Forgot password?</a></div>`:''}<button class="primary" type="submit">${setup?'Create workspace':register?'Create employee account':'Sign in'}</button><div class="auth-bottom">${register||setup?`<a href="/login" data-route="/login">Back to sign in</a>`:`${ceo?'Looking for employee access?':'Need an account?'} <a href="${ceo?'/login':'/register'}" data-route="${ceo?'/login':'/register'}">${ceo?'Employee login':'Create account'}</a>`}</div>${!ceo&&!register&&!setup?`<div class="auth-bottom"><a href="/ceo-login" data-route="/ceo-login">CEO login</a></div>`:''}</form></section></div>`;
 document.querySelectorAll('[data-route]').forEach(a=>a.onclick=e=>{e.preventDefault();goto(a.dataset.route)});document.querySelector('#forgot-link')?.addEventListener('click',e=>{e.preventDefault();toast('Password reset requires an email delivery service. Contact your workspace administrator.',true)});
 document.querySelector('#auth-form').onsubmit=async e=>{e.preventDefault();const f=new FormData(e.currentTarget),b=Object.fromEntries(f);const err=document.querySelector('#auth-error');try{if(setup){await api('/setup',{method:'POST',body:JSON.stringify(b)});toast('Workspace created. Sign in with your administrator account.');goto('/login');}else if(register){const r=await api('/register',{method:'POST',body:JSON.stringify(b)});toast(r.message);goto('/login');}else{await api('/login',{method:'POST',body:JSON.stringify({...b,kind:ceo?'ceo':'employee'})});goto('/dashboard');}}catch(x){err.innerHTML=`<div class="notice" style="background:#fff0f2;color:#b3334c">${esc(x.message)}</div>`;}};}
async function shell(key){app.innerHTML=`<div class="shell"><aside class="sidebar">${logo()}<div class="navlabel">Workspace</div><nav class="nav">${navItems.filter(i=>i[0]!=='employees'||['ceo','general_manager','manager','team_leader'].includes(me.role)).map(i=>`<a class="${key===i[0]?'active':''}" href="/${i[0]}" data-route="/${i[0]}"><span class="icon">${i[1]}</span><span class="nav-copy"><span class="label">${i[2]}</span><small>${i[3]}</small></span></a>`).join('')}</nav><div class="side-bottom"><div class="user-mini">${avatarMarkup(me.name)}<div><strong>${esc(me.name)}</strong><small>${esc(me.role.toUpperCase())}</small></div></div></div></aside><main class="main"><header class="topbar"><label class="searchbox"><span>⌕</span><input id="global-search" placeholder="Search your workspace..." value="${esc(searchTerm)}"></label><div class="top-actions"><button class="notification" title="Notifications">♧</button><div class="profile-menu-wrap"><button class="profile-menu-toggle" id="profile-menu-toggle" aria-expanded="false">${avatarMarkup(me.name,'top-avatar')}<span class="top-person"><strong>${esc(me.name)}</strong><small>${esc(me.role==='ceo'?'CEO':me.role.replaceAll('_',' ').replace(/^\w/,c=>c.toUpperCase()))}</small></span><span class="profile-chevron">⌄</span></button><div id="profile-dropdown" class="profile-dropdown hidden"><button data-profile-action="edit">Edit profile</button><button data-profile-action="help">Help</button><button data-profile-action="about">About Mitra Work</button><hr><button data-profile-action="logout" class="menu-logout">Logout</button></div></div></div></header><div class="content" id="page-content"><div class="empty">Loading your workspace…</div></div></main></div>`;
 document.querySelectorAll('[data-route]').forEach(a=>a.onclick=e=>{e.preventDefault();goto(a.dataset.route)});document.querySelector('#profile-menu-toggle').onclick=()=>{const menu=document.querySelector('#profile-dropdown');menu.classList.toggle('hidden');document.querySelector('#profile-menu-toggle').setAttribute('aria-expanded',String(!menu.classList.contains('hidden')));};document.querySelectorAll('[data-profile-action]').forEach(b=>b.onclick=async()=>{document.querySelector('#profile-dropdown').classList.add('hidden');if(b.dataset.profileAction==='edit')goto('/settings');else if(b.dataset.profileAction==='help')openHelpAssistant();else if(b.dataset.profileAction==='about')openAbout();else if(b.dataset.profileAction==='logout')await signOut();});document.querySelector('.notification').onclick=()=>goto('/dashboard');document.querySelector('#global-search').oninput=e=>{searchTerm=e.target.value;const term=searchTerm.trim();if(key==='tasks')loadTable(key,term);};
 try{if(key==='dashboard'){await dashboard();if(['ceo','general_manager','manager'].includes(me.role))await renderPlanningNotes();else {await renderDailyActivity();const employeeDash=await api(`/dashboard?date=${localDate()}`);await renderAssignedTasks(employeeDash.assignedTasks||[]);await renderReceivedNotes(employeeDash.notes||[]);}}else if(key==='analytics')await analytics();else if(key==='settings')settings();else if(key==='help')renderHelpPage();else if(key==='about')renderAboutPage();else if(key==='messages')await messagesPage();else if(key==='employees'){const employeeId=location.pathname.split('/')[2];if(employeeId)await employeeDetail(employeeId);else await employees();}else if(key==='tasks'){const taskId=location.pathname.split('/')[2];if(taskId)await taskDetail(taskId);else await loadTable(key,searchTerm);}else await loadTable(key,searchTerm);}catch(err){const host=document.querySelector('#page-content');if(host)host.innerHTML=`<section class="card load-error"><h2>Could not load this page</h2><p>${esc(err.message||'Please check your connection and try again.')}</p><button class="secondary" onclick="render()">Retry</button></section>`;console.error(err);}}
const titles={tasks:['Tasks','Assigned work, status, and daily updates.']};
function canAdmin(){return ['ceo','general_manager','manager','team_leader'].includes(me?.role)}
async function loadTable(type,q=''){
 if(type!=='tasks')return;
 const d=await api('/tasks'+(q?'?q='+encodeURIComponent(q):''));cache.tasks=d.items;
 let requests=[];if(me.role==='ceo'){try{requests=(await api('/task-deletion-requests')).requests}catch{}}
 const row=t=>`<tr>${canAdmin()?`<td>${esc(t.owner_name||'—')}</td>`:''}<td><button class="task-title-link" onclick="goto('/tasks/${t.id}')">${esc(t.title)}</button>${t.instructions?`<div class="task-instructions">${esc(t.instructions)}</div>`:''}${t.attachments?.length?`<div class="task-files">${t.attachments.map(a=>`<a href="/api/task-attachments/${a.id}" target="_blank" rel="noopener">↧ ${esc(a.filename)}</a>`).join(' · ')}</div>`:''}</td><td>${esc(t.due_date||'—')}</td><td>${badge(t.priority)}</td><td>${badge(t.status)}</td><td><button class="secondary task-actions-btn" onclick="taskActions(${t.id})">Actions</button></td></tr>`;
 document.querySelector('#page-content').innerHTML=`<div class="page-heading"><div><div class="eyebrow">WORKSPACE / TASKS</div><h1>Tasks</h1><p>Open a task to read instructions, files, and its dated work history.</p></div><button class="primary" onclick="openModal('tasks')">＋ Assign task</button></div>${requests.length?`<section class="card pending-delete-card"><div class="card-title"><div><h3>Deletion requests</h3><small>Tasks remain until CEO approval</small></div><span class="badge orange">${requests.length} pending</span></div>${requests.map(r=>`<article class="delete-request"><div><strong>${esc(r.title)}</strong><small>Requested by ${esc(r.requester_name)} · assigned to ${esc(r.owner_name)}</small></div><div class="row-actions"><button onclick="handleTaskDeletion(${r.id},'reject')">Reject</button><button class="danger" onclick="handleTaskDeletion(${r.id},'approve')">Approve deletion</button></div></article>`).join('')}</section>`:''}<section class="card"><div class="toolbar"><select id="status-filter" class="filter"><option value="">All task statuses</option>${['Open','In Progress','Completed'].map(x=>`<option>${x}</option>`).join('')}</select><span style="margin-left:auto;color:#82908e;font-size:11px">${d.items.length} tasks</span></div><div class="table-wrap"><table class="data-table"><thead><tr>${canAdmin()?'<th>Assigned to</th>':''}<th>Task</th><th>Due</th><th>Priority</th><th>Status</th><th>Actions</th></tr></thead><tbody id="task-rows">${d.items.map(row).join('')}</tbody></table>${!d.items.length?'<div class="empty"><strong>No tasks yet</strong><span>Assigned work will appear here.</span></div>':''}</div></section>`;
 document.querySelector('#status-filter').onchange=e=>{const v=e.target.value;document.querySelector('#task-rows').innerHTML=d.items.filter(t=>!v||t.status===v).map(row).join('')};
}
window.taskActions=id=>{const o=document.createElement('div');o.className='overlay';o.innerHTML=`<section class="modal"><div class="modal-head"><h2>Task actions</h2><button class="close">×</button></div><div class="task-action-list"><button class="secondary" data-act="open">Open task and history</button><button class="secondary" data-act="edit">Edit task</button><button class="danger" data-act="delete">Request deletion approval</button></div></section>`;document.body.append(o);o.querySelector('.close').onclick=()=>o.remove();o.querySelector('[data-act="open"]').onclick=()=>{o.remove();goto('/tasks/'+id)};o.querySelector('[data-act="edit"]').onclick=async()=>{o.remove();await openModal('tasks',id)};o.querySelector('[data-act="delete"]').onclick=async()=>{try{await api(`/tasks/${id}/request-deletion`,{method:'POST',body:'{}'});o.remove();toast('Deletion request sent to CEO.');await loadTable('tasks')}catch(e){toast(e.message,true)}}};
window.handleTaskDeletion=async(id,decision)=>{if(!confirm(decision==='approve'?'Approve deletion of this task?':'Reject this deletion request?'))return;try{await api(`/task-deletion-requests/${id}`,{method:'PATCH',body:JSON.stringify({decision})});toast(decision==='approve'?'Task deleted after approval.':'Deletion request rejected.');await loadTable('tasks')}catch(e){toast(e.message,true)}};
async function taskDetail(id){const d=await api(`/tasks/${encodeURIComponent(id)}`),t=d.task;cache.tasks=[...(cache.tasks||[]).filter(x=>x.id!==t.id),{...t,attachments:d.attachments}];const groups={};for(const h of d.updates)(groups[h.created_at.slice(0,10)]||=[]).push(h);document.querySelector('#page-content').innerHTML=`<div class="page-heading"><div><div class="eyebrow">WORKSPACE / TASKS / DETAILS</div><h1>${esc(t.title)}</h1><p>${badge(t.status)} · ${badge(t.priority)} · Due ${esc(t.due_date||'No due date')}</p></div><div class="dashboard-ctas"><button class="secondary" onclick="taskActions(${t.id})">Task actions</button><button class="secondary" onclick="goto('/tasks')">← All tasks</button></div></div><div class="section-grid"><section class="card"><div class="card-title"><h3>Task instructions</h3><small>Assigned to ${canAdmin()?esc(t.owner_name||getTaskOwnerName(t.owner_id)):'you'}</small></div><p class="task-description">${esc(t.instructions||'No additional instructions.')}</p>${d.attachments.length?`<div class="task-attachment-list"><h4>Task files</h4>${d.attachments.map(a=>`<a href="/api/task-attachments/${a.id}" target="_blank" rel="noopener">▤ ${esc(a.filename)} <small>· ${(a.size/1024).toFixed(0)} KB</small></a>`).join('')}</div>`:'<div class="empty">No files attached.</div>'}${d.deletionRequest?'<div class="notice">Deletion request is waiting for CEO approval.</div>':''}</section><section class="card"><div class="card-title"><div><h3>Log work update</h3><small>Your update is saved with date and time.</small></div></div><form id="task-update-form"><div class="field"><label>Status</label><select name="status">${['Open','In Progress','Completed'].map(x=>`<option ${x===t.status?'selected':''}>${x}</option>`).join('')}</select></div><div class="field" style="margin-top:12px"><label>What did you work on?</label><textarea name="summary" required maxlength="4000" rows="4" placeholder="Progress, blockers, or completion details…"></textarea></div><div class="form-footer"><button class="primary">Save update</button></div></form></section></div><section class="card task-history-card"><div class="card-title"><div><h3>Task history</h3><small>Changes grouped by day</small></div><span class="badge blue">${d.updates.length} updates</span></div>${Object.keys(groups).length?Object.keys(groups).sort().reverse().map(day=>`<section class="history-day"><h4>${new Date(day+'T12:00:00').toLocaleDateString(undefined,{weekday:'long',month:'long',day:'numeric',year:'numeric'})}</h4>${groups[day].map(h=>`<article class="history-entry"><div class="history-time">${new Date(h.created_at+'Z').toLocaleTimeString(undefined,{hour:'2-digit',minute:'2-digit'})}</div><div><strong>${esc(h.user_name)}</strong>${h.new_status&&h.new_status!==h.old_status?`<span> changed status from ${esc(h.old_status)} to ${esc(h.new_status)}</span>`:''}<p>${esc(h.summary)}</p></div></article>`).join('')}</section>`).join(''):'<div class="empty">No updates yet. Add the first update above.</div>'}</section>`;document.querySelector('#task-update-form').onsubmit=async e=>{e.preventDefault();try{await api(`/tasks/${id}/updates`,{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});toast('Task update saved.');await taskDetail(id)}catch(x){toast(x.message,true)}}}
function getTaskOwnerName(id){return cache.tasks?.find(x=>x.id===id)?.owner_name||'employee'}
async function messagesPage(){const [directory,mail]=await Promise.all([api('/directory'),api('/messages')]);let mode='inbox';const host=document.querySelector('#page-content');const paint=()=>{const list=mail[mode]||[];host.innerHTML=`<div class="page-heading"><div><div class="eyebrow">WORKSPACE / MESSAGES</div><h1>Messages</h1><p>Send an in-app message to the CEO or a teammate.</p></div><span class="badge blue">${mail.inbox.filter(x=>!x.read_at).length} unread</span></div><div class="section-grid message-layout"><section class="card"><div class="card-title"><div><h3>Compose message</h3><small>Choose a recipient and send your update</small></div></div><form id="message-form"><div class="field"><label>Send to</label><select name="recipient_id" required><option value="">Select CEO or teammate</option>${directory.people.map(x=>`<option value="${x.id}">${esc(x.name)} · ${x.role==='ceo'?'CEO':esc(x.department||x.role)}</option>`).join('')}</select></div><div class="field" style="margin-top:12px"><label>Subject</label><input name="subject" maxlength="160" required placeholder="What is this about?"></div><div class="field" style="margin-top:12px"><label>Message</label><textarea name="message" rows="6" maxlength="8000" required placeholder="Write your message…"></textarea></div><div class="form-footer"><button class="primary">Send message</button></div></form></section><section class="card"><div class="card-title"><div><h3>Mailbox</h3><small>Messages in this workspace</small></div></div><div class="toolbar"><button class="${mode==='inbox'?'primary':'secondary'}" id="inbox-tab">Inbox</button><button class="${mode==='sent'?'primary':'secondary'}" id="sent-tab">Sent</button></div>${list.length?list.map(m=>`<article class="mail-item ${m.read_at||mode==='sent'?'':'unread'}"><div class="mail-item-head"><strong>${esc(m.subject)}</strong><small>${mode==='inbox'?'From':'To'} ${esc(mode==='inbox'?m.sender_name:m.recipient_name)} · ${new Date(m.created_at+'Z').toLocaleString()}</small></div><p>${esc(m.message)}</p>${mode==='inbox'&&!m.read_at?`<button class="secondary" onclick="markMessageRead(${m.id})">Mark read</button>`:''}</article>`).join(''):'<div class="empty">No messages in this folder.</div>'}</section></div>`;document.querySelector('#inbox-tab').onclick=()=>{mode='inbox';paint()};document.querySelector('#sent-tab').onclick=()=>{mode='sent';paint()};document.querySelector('#message-form').onsubmit=async e=>{e.preventDefault();try{await api('/messages',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(e.currentTarget)))});toast('Message sent.');const latest=await api('/messages');mail.sent=latest.sent;paint()}catch(x){toast(x.message,true)}}};paint()}
window.markMessageRead=async id=>{try{await api(`/messages/${id}/read`,{method:'PATCH',body:'{}'});goto('/messages')}catch(e){toast(e.message,true)}};
window.downloadWorkReport=()=>{const month=document.querySelector('#team-export-month')?.value||localDate().slice(0,7);window.location.href=`/api/reports/daily-work.xls?month=${encodeURIComponent(month)}`;};
window.downloadEmployeeReport=id=>{const month=document.querySelector('#employee-export-month')?.value||localDate().slice(0,7);window.location.href=`/api/reports/daily-work.xls?month=${encodeURIComponent(month)}&employee_id=${encodeURIComponent(id)}`;};

function person(n){return `<div class="person-cell"><span class="mini-avatar">${initials(n)}</span>${esc(n)}</div>`}function badge(s){const v=String(s||'—');const cls=/completed|active/i.test(v)?'green':/urgent|rejected/i.test(v)?'red':/high/i.test(v)?'orange':/progress|open/i.test(v)?'blue':'';return `<span class="badge ${cls}">${esc(v)}</span>`}
const config={tasks:{title:'Task',fields:[['title','Task','text',1],['project_name','Project name','text'],['due_date','Due date','date'],['priority','Priority','select',['Low','Medium','High','Urgent']],['status','Status','select',['Open','In Progress','Completed']],['instructions','Instructions','textarea']]}};
window.openModal=async(type,id)=>{const c=config[type];if(!c)return;const existing=id?cache[type]?.find(x=>x.id===id):null;let inputs=c.fields.map(([name,label,kind,opts])=>`<div class="field"><label>${label}</label>${Array.isArray(opts)?`<select name="${name}">${opts.map(o=>`<option ${existing?.[name]===o?'selected':''}>${o}</option>`).join('')}</select>`:kind==='textarea'?`<textarea name="${name}" rows="3" placeholder="Add steps or delivery requirements">${esc(existing?.[name]||'')}</textarea>`:`<input name="${name}" type="${kind}" ${opts===1?'required':''} value="${esc(existing?.[name]??'')}" ${name==='probability'?'min="0" max="100"':''} ${name==='value'?'min="0"':''}`}></div>`).join('');if(canAdmin()){const team=await api('/employees');const active=team.items.filter(x=>x.role!=='ceo'&&x.status==='active');inputs+=`<div class="field full"><label>Assigned employee</label><select name="owner_id"><option value="${me.id}">My records</option>${active.map(x=>`<option value="${x.id}" ${Number(existing?.owner_id)===x.id?'selected':''}>${esc(x.name)} · ${esc(x.department)}</option>`).join('')}</select></div>`;}if(type==='tasks')inputs+=`<div class="field full"><label>Attach files (PDF, Office, image, or text · up to 3 MB on Vercel, 8 MB locally)</label><input type="file" name="task_files" multiple accept=".pdf,.doc,.docx,.xls,.xlsx,.ppt,.pptx,.txt,.png,.jpg,.jpeg,.webp"></div>`;const o=document.createElement('div');o.className='overlay';o.innerHTML=`<form class="modal" id="record-form"><div class="modal-head"><h2>${id?'Edit':'Add'} ${c.title}</h2><button type="button" class="close">×</button></div><div class="form-grid">${inputs}</div><div class="form-footer"><button class="secondary cancel" type="button">Cancel</button><button class="primary">${id?'Save changes':'Create '+c.title.toLowerCase()}</button></div></form>`;document.body.append(o);o.querySelector('.close').onclick=o.querySelector('.cancel').onclick=()=>o.remove();o.onclick=e=>{if(e.target===o)o.remove()};o.querySelector('form').onsubmit=async e=>{e.preventDefault();try{const formData=new FormData(e.currentTarget),b={};for(const [key,value] of formData.entries())if(key!=='task_files')b[key]=value;if(type==='tasks'){const files=[...formData.getAll('task_files')].filter(f=>f instanceof File&&f.size);b.attachments=await Promise.all(files.map(file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve({name:file.name,type:file.type||'application/octet-stream',data:reader.result});reader.onerror=()=>reject(Error('Could not read '+file.name));reader.readAsDataURL(file);})));}await api(`/${type}${id?'/'+id:''}`,{method:id?'PUT':'POST',body:JSON.stringify(b)});o.remove();toast(`${c.title} ${id?'updated':'created'}.`);await loadTable(type,searchTerm);}catch(x){toast(x.message,true)}};};
function roleName(role){return ({employee:'Employee',team_leader:'Team leader',manager:'Manager',general_manager:'General manager',ceo:'CEO'}[role]||String(role||'').replaceAll('_',' '));}
async function employees(){
 const d=await api('/employees'),waiting=d.items.filter(x=>x.status==='pending'),members=d.items.filter(x=>x.role!=='ceo');
 const host=document.querySelector('#page-content');
 host.innerHTML=`<div class="page-heading"><div><div class="eyebrow">WORKSPACE / PEOPLE</div><h1>Team</h1><p>Employee roles, activity, and individual work reports.</p></div><div class="dashboard-ctas"><label>Month <input id="team-export-month" type="month" value="${localDate().slice(0,7)}"></label><button class="primary" onclick="downloadWorkReport()">Download all employee Excel workbooks</button></div></div>${waiting.length?`<div class="card" style="margin-bottom:18px"><div class="card-title"><h3>Pending requests</h3><span class="badge orange">${waiting.length} awaiting review</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Name</th><th>Email</th><th>Requested</th><th>Action</th></tr></thead><tbody>${waiting.map(x=>`<tr><td>${person(x.name)}</td><td>${esc(x.email)}</td><td>${new Date(x.created_at+'Z').toLocaleDateString()}</td><td><div class="row-actions"><button data-employee-status="active" data-employee-id="${x.id}">Approve</button><button data-employee-status="rejected" data-employee-id="${x.id}">Reject</button></div></td></tr>`).join('')}</tbody></table></div></div>`:''}<div class="card"><div class="card-title"><h3>Workspace members</h3><small>${members.length} employees</small></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Employee</th><th>Email</th><th>Department</th><th>Role</th><th>Status</th></tr></thead><tbody>${members.map(x=>`<tr><td><a class="employee-profile-link" href="/employees/${x.id}" data-employee-profile="${x.id}">${person(x.name)}<small>View profile →</small></a></td><td>${esc(x.email)}</td><td>${esc(x.department)}</td><td><button class="role-edit" type="button" title="Change role" aria-label="Change role for ${esc(x.name)}" data-employee-role="${x.id}" data-employee-name="${esc(x.name)}" data-current-role="${esc(x.role)}">${esc(roleName(x.role))}<span aria-hidden="true">⌄</span></button></td><td>${badge(x.status)}</td></tr>`).join('')}</tbody></table></div></div>`;
 host.querySelectorAll('[data-employee-profile]').forEach(a=>a.onclick=e=>{e.preventDefault();goto('/employees/'+a.dataset.employeeProfile)});
 host.querySelectorAll('[data-employee-role]').forEach(b=>b.onclick=()=>employeePromote(Number(b.dataset.employeeRole),b.dataset.employeeName,b.dataset.currentRole));
 host.querySelectorAll('[data-employee-status]').forEach(b=>b.onclick=()=>employeeAction(Number(b.dataset.employeeId),b.dataset.employeeStatus));
}
window.employeeAction=async(id,status)=>{try{await api('/employees',{method:'PATCH',body:JSON.stringify({id,status})});toast(status==='active'?'Employee approved.':status==='rejected'?'Request rejected.':'Role updated.');employees();}catch(e){toast(e.message,true)}};
async function analytics(){
 const d=await api(`/dashboard?date=${localDate()}`),p=d.taskProgress||{open:0,inProgress:0,completed:0},all=d.totalTasks??(p.open+p.inProgress+p.completed),doneRate=all?Math.round(p.completed/all*100):0,managerView=canAdmin();
 const people=managerView?(d.team||[]):[];
 document.querySelector('#page-content').innerHTML=`<div class="page-heading"><div><div class="eyebrow">WORKSPACE / ANALYTICS</div><h1>${managerView?'Team task analytics':'My task analytics'}</h1><p>${managerView?'Tasks assigned across the team, grouped by current status.':'Only tasks assigned to your account, grouped by current status.'}</p></div></div><div class="cards">${[['Assigned tasks',all,'▦'],['Open',p.open,'○'],['In progress',p.inProgress,'◷'],['Completed',p.completed,'✓']].map(x=>`<div class="card"><div class="stat"><div><small>${x[0]}</small><strong>${x[1]}</strong></div><span class="stat-icon">${x[2]}</span></div></div>`).join('')}</div><section class="card"><div class="card-title"><div><h3>${managerView?'Employee workload':'My completion'}</h3><small>${managerView?'Each row shows one employee’s assigned tasks.':'Completion rate for your assigned tasks.'}</small></div>${badge(`${doneRate}% completed`)}</div>${managerView?(people.length?people.map(x=>`<div class="team-work-row"><strong>${esc(x.name)} <small>${esc(roleName(x.role))}</small></strong><div>${badge('Open')} ${Number(x.open_tasks)||0} &nbsp; ${badge('In Progress')} ${Number(x.in_progress_tasks)||0} &nbsp; ${badge('Completed')} ${Number(x.completed_tasks)||0} <span class="team-total">${Number(x.total_tasks)||0} total</span></div></div>`).join(''):'<div class="empty">Employee task totals will appear here when work is assigned.</div>'):`<div class="progress-row"><span>Open</span><div class="progress-track"><i style="width:${all?p.open/all*100:0}%"></i></div><strong>${p.open}</strong></div><div class="progress-row"><span>In progress</span><div class="progress-track"><i class="in-progress" style="width:${all?p.inProgress/all*100:0}%"></i></div><strong>${p.inProgress}</strong></div><div class="progress-row"><span>Completed</span><div class="progress-track"><i class="completed" style="width:${all?p.completed/all*100:0}%"></i></div><strong>${p.completed}</strong></div>`}</section>`;
 await renderPersonalNotes();
}
async function renderPersonalNotes(){let date=localDate();const host=document.querySelector('#page-content');const paint=async()=>{const data=await api(`/my-notes?date=${date}`);let card=host.querySelector('.personal-notes');if(!card){host.insertAdjacentHTML('beforeend','<section class="card personal-notes"></section>');card=host.querySelector('.personal-notes');}card.innerHTML=`<div class="card-title"><div><h3>My private notes</h3><small>Only you can view these notes. Saved by date.</small></div><label class="date-picker-label">Date <input id="private-note-date" type="date" value="${date}"></label></div><form id="personal-note-form"><div class="field"><label>Private note</label><textarea name="summary" rows="4" maxlength="4000" placeholder="Plans, reminders, or personal work notes…">${esc(data.note?.summary||'')}</textarea></div><div class="daily-footer"><small>${data.note?'Saved':'Private'} · ${date}</small><button class="primary">Save private note</button></div></form>`;card.querySelector('#private-note-date').onchange=async e=>{date=e.target.value;await paint()};card.querySelector('#personal-note-form').onsubmit=async e=>{e.preventDefault();try{await api('/my-notes',{method:'PUT',body:JSON.stringify({date,summary:new FormData(e.currentTarget).get('summary')})});toast('Private note saved.');await paint();}catch(x){toast(x.message,true)}}};await paint();}

function settings(){document.querySelector('#page-content').innerHTML=`<div class="page-heading"><div><div class="eyebrow">ACCOUNT / PROFILE</div><h1>Edit profile</h1><p>Update your professional profile and the details your team sees.</p></div></div><section class="card profile-editor"><form id="profile-form"><div class="profile-photo-row">${me.photo?`<img class="profile-photo-preview" id="photo-preview" src="${me.photo}" alt="Profile photo">`:`<div class="profile-photo-preview initials-preview" id="photo-preview">${initials(me.name)}</div>`}<div><label class="field"><span class="field-label">Profile photo</span><input type="file" name="photo_file" accept="image/png,image/jpeg,image/webp"></label><small>PNG, JPEG, or WebP · max 1.5 MB</small></div></div><div class="form-grid profile-grid"><div class="field"><label>Full name</label><input name="name" required maxlength="120" value="${esc(me.name)}"></div><div class="field"><label>Job title</label><input name="profile_title" placeholder="e.g. Sales Executive" value="${esc(me.profile_title||'')}"></div><div class="field"><label>Department / field</label><input name="department" required value="${esc(me.department||'Sales')}"></div><div class="field"><label>Phone</label><input name="phone" type="tel" value="${esc(me.phone||'')}"></div><div class="field full"><label>Professional summary</label><textarea name="bio" rows="4" maxlength="2000" placeholder="A short introduction, experience, and focus areas…">${esc(me.bio||'')}</textarea></div><div class="field full"><label>Skills</label><input name="skills" maxlength="1200" placeholder="React, CRM, Client management" value="${esc(me.skills||'')}"><small>Separate skills with commas.</small></div><div class="field full"><label>Email</label><input disabled value="${esc(me.email)}"></div></div><div class="form-footer"><button type="button" class="secondary" onclick="goto('/dashboard')">Cancel</button><button class="primary">Save profile</button></div></form></section>`;const form=document.querySelector('#profile-form'),photoInput=form.elements.photo_file;photoInput.onchange=()=>{const file=photoInput.files[0];if(!file)return;if(file.size>1.5*1024*1024){toast('Photo must be 1.5 MB or smaller.',true);photoInput.value='';return;}const reader=new FileReader();reader.onload=()=>{document.querySelector('#photo-preview').outerHTML=`<img class="profile-photo-preview" id="photo-preview" src="${reader.result}" alt="Profile photo preview">`;};reader.readAsDataURL(file);};form.onsubmit=async e=>{e.preventDefault();try{const values=Object.fromEntries(new FormData(form));delete values.photo_file;const file=photoInput.files[0];if(file)values.photo=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(Error('Could not read the profile photo.'));reader.readAsDataURL(file);});const result=await api('/me',{method:'PATCH',body:JSON.stringify(values)});me=result.user;toast('Profile updated.');await shell('settings');}catch(x){toast(x.message,true)}};}
render();
function localDate(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
async function renderDailyActivity(){const date=localDate();const data=await api(`/daily-activity?date=${date}`);let host=document.querySelector('#daily-activity');if(!host){host=document.createElement('div');host.id='daily-activity';document.querySelector('#page-content').append(host);}host.innerHTML=`<section class="card daily-card"><div class="card-title"><div><h3>My daily activity</h3><small>Log your work for ${new Date(`${date}T12:00:00`).toLocaleDateString(undefined,{weekday:'long',month:'short',day:'numeric'})}</small></div><span class="badge ${data.today?'green':'blue'}">${data.today?'Saved':'Not added yet'}</span></div><form id="daily-form"><div class="field"><label>Project name</label><input name="project_name" maxlength="160" value="${esc(data.today?.project_name||'')}" placeholder="Which project did you work on?"></div><div class="field"><label>What did you work on today?</label><textarea name="summary" rows="4" maxlength="4000" required placeholder="Add your completed work, progress, or blockers…">${esc(data.today?.summary||'')}</textarea></div><div class="daily-footer"><small>Your daily entry is private to your account.</small><button class="primary">${data.today?'Update today’s activity':'Save today’s activity'}</button></div></form>${data.history.length?`<div class="daily-history"><h4>Recent daily updates</h4>${data.history.map(x=>`<article><time>${new Date(`${x.activity_date}T12:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}</time><p><strong>${esc(x.project_name||'Work update')}</strong> · ${esc(x.summary)}</p></article>`).join('')}</div>`:''}</section>`;document.querySelector('#daily-form').onsubmit=async e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.currentTarget));try{await api('/daily-activity',{method:'PUT',body:JSON.stringify({date,...values})});toast(data.today?'Daily activity updated.':'Daily activity saved.');await renderDailyActivity();}catch(x){toast(x.message,true)}};}
async function renderPlanningNotes(){let host=document.querySelector('#daily-activity');if(!host){host=document.createElement('div');host.id='daily-activity';document.querySelector('#page-content').append(host);}const tomorrow=new Date(Date.now()+86400000);const date=`${tomorrow.getFullYear()}-${String(tomorrow.getMonth()+1).padStart(2,'0')}-${String(tomorrow.getDate()).padStart(2,'0')}`;const data=await api(`/planning-notes?date=${date}`);host.innerHTML=`<section class="card planning-card"><div class="card-title"><div><div class="eyebrow">EXECUTIVE PLANNING</div><h3>Tomorrow’s plan</h3><small>Plan priorities and follow-ups for the next day.</small></div><span class="badge blue">${data.note?'Saved':'Draft'}</span></div><form id="planning-form"><div class="field"><label>Plan date</label><input type="date" name="date" value="${date}" required></div><div class="field" style="margin-top:14px"><label>Notes and priorities</label><textarea name="summary" rows="4" maxlength="4000" required placeholder="Key decisions, meetings, and priorities…">${esc(data.note?.summary||'')}</textarea></div><div class="daily-footer"><small>Private executive notes · saved by date</small><button class="primary">${data.note?'Update plan':'Save plan'}</button></div></form></section>`;const form=document.querySelector('#planning-form');form.elements.date.onchange=async()=>{const selected=await api(`/planning-notes?date=${form.elements.date.value}`);form.elements.summary.value=selected.note?.summary||'';form.querySelector('button').textContent=selected.note?'Update plan':'Save plan';};form.onsubmit=async e=>{e.preventDefault();try{await api('/planning-notes',{method:'PUT',body:JSON.stringify(Object.fromEntries(new FormData(form)))});toast('Planning notes saved.');await renderPlanningNotes();}catch(x){toast(x.message,true)}};}
window.employeePromote=(id,name,current)=>{const options=[['employee','Employee'],['team_leader','Team leader'],['manager','Manager'],['general_manager','General manager']];const overlay=document.createElement('div');overlay.className='overlay';overlay.innerHTML=`<form class="modal" id="promotion-form"><div class="modal-head"><div><div class="eyebrow">EMPLOYEE ACTION</div><h2>Update title</h2></div><button type="button" class="close">×</button></div><p class="muted">Select an approved title for ${esc(name)}. The change applies only after you confirm.</p><div class="field"><label>Role / title</label><select name="role">${options.map(([v,label])=>`<option value="${v}" ${v===current?'selected':''}>${label}</option>`).join('')}</select></div><div class="form-footer"><button type="button" class="secondary cancel">Cancel</button><button class="primary">Confirm change</button></div></form>`;document.body.append(overlay);overlay.querySelector('.close').onclick=overlay.querySelector('.cancel').onclick=()=>overlay.remove();overlay.querySelector('form').onsubmit=async e=>{e.preventDefault();try{await api('/employees',{method:'PATCH',body:JSON.stringify({id,role:new FormData(e.currentTarget).get('role')})});overlay.remove();toast('Employee title updated.');await employees();}catch(x){toast(x.message,true)}};};
async function renderReceivedNotes(notes){const host=document.createElement('section');host.className='card received-notes';host.innerHTML=`<div class="card-title"><div><h3>Notes from management</h3><small>Messages shared with you</small></div><span class="badge blue">${notes.length}</span></div>${notes.length?notes.map(n=>`<article class="received-note"><p>${esc(n.note)}</p><small>${esc(n.sender_name)} · ${new Date(n.created_at+'Z').toLocaleString()}</small></article>`).join(''):'<div class="empty">No notes yet.</div>'}`;document.querySelector('#page-content').append(host);}
async function renderAssignedTasks(tasks){const host=document.createElement('section');host.className='card assigned-tasks';host.innerHTML=`<div class="card-title"><div><h3>Tasks assigned to me</h3><small>Open any task to add a dated update</small></div><span class="badge blue">${tasks.length} total</span></div>${tasks.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Project</th><th>Task</th><th>Due</th><th>Priority</th><th>Status</th></tr></thead><tbody>${tasks.map(t=>`<tr><td>${esc(t.project_name||'—')}</td><td><button class="task-title-link" onclick="goto('/tasks/${t.id}')">${esc(t.title)}</button>${t.instructions?`<div class="task-instructions">${esc(t.instructions)}</div>`:''}${t.attachments?.length?`<div class="task-files">${t.attachments.map(a=>`<a href="/api/task-attachments/${a.id}" target="_blank" rel="noopener">↧ ${esc(a.filename)}</a>`).join(' · ')}</div>`:''}</td><td>${esc(t.due_date||'—')}</td><td>${badge(t.priority)}</td><td>${badge(t.status)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No tasks assigned yet.</div>'}`;document.querySelector('#page-content').append(host);}
function renderEmployeeRecent(items,name){const list=document.querySelector('.employee-recent-list');if(!list)return;if(!items.length){list.innerHTML='<div class="empty">No recent actions recorded for this employee.</div>';return;}list.innerHTML=items.map(a=>`<article class="activity-row"><span class="activity-dot">↗</span><div><strong>${esc(a.message)}</strong><small>${new Date(a.created_at+'Z').toLocaleString()}</small></div></article>`).join('')}
async function employeeDetail(id){try{const selectedDate=new URLSearchParams(location.search).get('date')||localDate(),d=await api(`/employees/${encodeURIComponent(id)}?date=${selectedDate}`),e=d.employee,taskCounts={open:d.tasks.filter(t=>t.status==='Open').length,inProgress:d.tasks.filter(t=>t.status==='In Progress').length,completed:d.tasks.filter(t=>t.status==='Completed').length};document.querySelector('#page-content').innerHTML=`<div class="page-heading"><div><div class="eyebrow">WORKSPACE / TEAM / PROFILE</div><h1>${esc(e.name)}</h1><p>${esc(e.profile_title||e.department||'Team member')} · ${esc(e.email)} · ${badge(e.status)}</p></div><div class="dashboard-ctas"><label>Month <input id="employee-export-month" type="month" value="${localDate().slice(0,7)}"></label><button class="primary" onclick="downloadEmployeeReport(${e.id})">Download monthly Excel report</button><button class="secondary" onclick="goto('/employees')">← Team</button></div></div><div class="cards employee-stats"><div class="card"><small>Open tasks</small><strong>${taskCounts.open}</strong></div><div class="card"><small>In progress</small><strong>${taskCounts.inProgress}</strong></div><div class="card"><small>Completed tasks</small><strong>${taskCounts.completed}</strong></div><div class="card"><small>Total assigned</small><strong>${d.tasks.length}</strong></div></div><section class="card employee-recent"><div class="card-title"><div><h3>Recent activity</h3><small>Actions performed by ${esc(e.name)}</small></div><span class="badge blue">${d.recent.length}</span></div><div class="employee-recent-list"></div></section><section class="card"><div class="card-title"><div><h3>Assigned tasks</h3><small>Work currently assigned to ${esc(e.name)}</small></div><button class="primary" onclick="assignTaskToEmployee(${e.id})">＋ Assign task</button></div>${d.tasks.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Task</th><th>Due</th><th>Priority</th><th>Status</th></tr></thead><tbody>${d.tasks.map(t=>`<tr><td><button class="task-title-link" onclick="goto('/tasks/${t.id}')">${esc(t.title)}</button></td><td>${esc(t.due_date||'—')}</td><td>${badge(t.priority)}</td><td>${badge(t.status)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No tasks assigned.</div>'}</section><div class="section-grid"><section class="card"><div class="card-title"><div><h3>Daily activity</h3><small>Select a date to see that day's update</small></div><label class="date-picker-label">Date <input id="activity-date" type="date" value="${selectedDate}"></label></div><div class="selected-daily">${d.selectedDaily?`<p>${esc(d.selectedDaily.summary)}</p><small>Updated ${new Date(d.selectedDaily.updated_at+'Z').toLocaleString()}</small>`:'<div class="empty">No update for this date.</div>'}</div><div class="daily-history">${d.daily.map(x=>`<article><time>${new Date(`${x.activity_date}T12:00:00`).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'})}</time><p>${esc(x.summary)}</p></article>`).join('')}</div></section><section class="card"><div class="card-title"><div><h3>Message ${esc(e.name.split(' ')[0])}</h3><small>Send a private note to the employee</small></div></div><form id="employee-note-form"><div class="field"><textarea name="note" rows="4" maxlength="4000" required placeholder="Write an instruction or note…"></textarea></div><div class="form-footer"><button class="primary">Send note</button></div></form><div class="daily-history">${d.notes.map(n=>`<article><time>${new Date(n.created_at+'Z').toLocaleDateString()}</time><p>${esc(n.note)}</p><small>Sent by ${esc(n.sender_name)}</small></article>`).join('')}</div></section></div><section class="card project-card"><div class="card-title"><div><h3>Projects</h3><small>${d.projects.length} total · ${d.stats.projects} completed</small></div><button class="secondary" onclick="addEmployeeProject(${e.id})">＋ Add project</button></div>${d.projects.length?d.projects.map(x=>`<article class="history-entry"><strong>${esc(x.name)}</strong> · ${badge(x.status)}</article>`).join(''):'<div class="empty">No projects added.</div>'}</section>`;renderEmployeeRecent(d.recent,e.name);document.querySelector('#activity-date').onchange=ev=>{const u=new URL(location.href);u.searchParams.set('date',ev.target.value);history.replaceState({},'',u);employeeDetail(id)};document.querySelector('#employee-note-form').onsubmit=async ev=>{ev.preventDefault();try{await api('/employee-notes',{method:'POST',body:JSON.stringify({employee_id:e.id,note:new FormData(ev.currentTarget).get('note')})});toast('Note sent to employee.');employeeDetail(id)}catch(x){toast(x.message,true)}}}catch(err){const host=document.querySelector('#page-content');if(host)host.innerHTML=`<section class="card load-error"><h2>Team profile could not load</h2><p>${esc(err.message||'Please retry.')}</p><button class="secondary" onclick="employeeDetail('${esc(id)}')">Retry</button><button class="secondary" onclick="goto('/employees')">Back to team</button></section>`;}}

window.addEmployeeProject=async(owner_id)=>{const overlay=document.createElement('div');overlay.className='overlay';overlay.innerHTML=`<form id="project-form" class="modal"><div class="modal-head"><h2>Add project</h2><button type="button" class="close">×</button></div><div class="field"><label>Project name</label><input name="name" required maxlength="160"></div><div class="field" style="margin-top:12px"><label>Status</label><select name="status"><option>In Progress</option><option>Completed</option><option>On Hold</option></select></div><div class="form-footer"><button type="button" class="secondary cancel">Cancel</button><button class="primary">Save project</button></div></form>`;document.body.append(overlay);overlay.querySelector('.close').onclick=overlay.querySelector('.cancel').onclick=()=>overlay.remove();overlay.querySelector('form').onsubmit=async ev=>{ev.preventDefault();try{await api('/employee-projects',{method:'POST',body:JSON.stringify({owner_id,...Object.fromEntries(new FormData(ev.currentTarget))})});toast('Project added.');overlay.remove();employeeDetail(owner_id);}catch(x){toast(x.message,true)}};};

window.assignTaskToEmployee=async id=>{await openModal('tasks');const owner=document.querySelector('#record-form select[name=owner_id]');if(owner)owner.value=String(id);};

async function signOut(){const button=document.querySelector('[data-profile-action="logout"]');if(button){button.disabled=true;button.textContent='Signing out…'}try{await api('/logout',{method:'POST'});}catch(error){toast('Could not reach the server to end this session. Please try again.',true);if(button){button.disabled=false;button.textContent='Logout'}return;}me=null;history.replaceState({},'', '/');await render();}
const helpArticles=[
{title:'Dashboard and daily overview',keywords:'dashboard home overview tasks progress recent activity missing daily updates CEO team members',text:'The Dashboard summarizes open, in progress, and completed tasks, recent activity, and (for administrators) team workload and daily updates due. Employees can submit their daily work update and review assigned tasks.'},
{title:'Tasks and task history',keywords:'task assign create status priority due date instructions files attachment update history delete approval',text:'Tasks hold a title, due date, priority, status, instructions, optional project name, and attachments. Employees can open a task, update its status, and log progress; the app keeps a dated task history. Employees request task deletion, and the CEO approves or rejects it.'},
{title:'Daily updates and planning notes',keywords:'daily update today work summary planning notes CEO manager',text:'Employees record what they worked on in Daily Activity; the latest updates appear on the dashboard. Administrators can keep private planning notes for their own workspace. Daily entries are saved by date so recent work can be reviewed.'},
{title:'Team and employee profiles',keywords:'team employees people profile approve pending role department skills reports excel',text:'Administrators can open Team to review employee profiles, roles, departments, and activity. Pending employee requests can be approved or rejected. Depending on role, administrators can promote team members and download monthly Excel workbooks.'},
{title:'Messages',keywords:'message send inbox sent read CEO teammate communication',text:'Messages lets you choose the CEO or a teammate, add a subject, and send an in-app note. Inbox and Sent tabs show correspondence; unread inbox messages can be marked as read.'},
{title:'Analytics',keywords:'analytics workload completion open in progress completed charts',text:'Analytics summarizes task counts by status and groups current workload by assigned employee. The numbers reflect the tasks currently stored in the workspace.'},
{title:'Account and sign in',keywords:'account login CEO employee password logout profile settings email',text:'Use CEO Login for the CEO account and Employee Login for employee accounts. Each account email belongs to one role. Edit profile opens account settings; Logout ends the current session and returns to the welcome page.'},
{title:'Data, privacy, and technical setup',keywords:'database SQLite Turso Vercel Blob attachments security password scrypt storage',text:'Locally, records are stored in SQLite in data/novacrm.sqlite and attachments in data/uploads. Passwords are hashed with scrypt and sessions use HTTP-only cookies. A Vercel deployment uses Turso for database storage and private Vercel Blob for attachments. Production should use HTTPS and have rate limiting, CSRF protection, backups, and monitoring.'}
];
function helpAnswer(question){const words=question.toLowerCase().match(/[\p{L}\p{N}]+/gu)||[];const scored=helpArticles.map(a=>({a,score:words.reduce((n,w)=>n+(a.keywords.toLowerCase().includes(w)?(w.length>3?2:1):0),0)})).sort((a,b)=>b.score-a.score);if(!scored[0]?.score)return 'I can help with the Dashboard, tasks, daily updates, team and employee profiles, messages, analytics, account access, and how this app stores its data. Try asking a more specific question, such as “How do I update a task?” or “Where do I find employee reports?”';return scored.slice(0,scored[0].score>2?2:1).map(x=>x.a.title+'\n'+x.a.text).join('\n\n');}
function openHelpAssistant(){const o=document.createElement('div');o.className='overlay';o.innerHTML='<section class="modal help-modal" role="dialog" aria-modal="true" aria-labelledby="help-title"><div class="modal-head"><div><div class="eyebrow">MITRA WORK SUPPORT</div><h2 id="help-title">Help assistant</h2></div><button class="close" aria-label="Close">×</button></div><p class="muted">Ask how a feature works or where to find it.</p><div class="help-chat-log" id="help-chat-log" aria-live="polite"><div class="help-bubble bot"><strong>Mitra Work helper</strong><p>Hi! Ask me about tasks, daily updates, team management, messages, reports, or account access.</p></div></div><form class="help-chat-form" id="help-chat-form"><input name="question" required maxlength="500" autocomplete="off" placeholder="Ask a question about Mitra Work…" aria-label="Your question"><button class="primary">Ask</button></form><div class="help-note">Answers use the app’s built-in feature guide.</div></section>';document.body.append(o);const close=()=>o.remove();o.querySelector('.close').onclick=close;o.onclick=e=>{if(e.target===o)close()};o.querySelector('#help-chat-form').onsubmit=e=>{e.preventDefault();const input=e.currentTarget.elements.question,question=input.value.trim();if(!question)return;const log=o.querySelector('#help-chat-log');const userBubble=document.createElement('div');userBubble.className='help-bubble user';const userText=document.createElement('p');userText.textContent=question;userBubble.append(userText);const botBubble=document.createElement('div');botBubble.className='help-bubble bot';const botTitle=document.createElement('strong');botTitle.textContent='Mitra Work helper';const botText=document.createElement('p');botText.innerHTML=esc(helpAnswer(question)).split(String.fromCharCode(10)).join('<br>');botBubble.append(botTitle,botText);log.append(userBubble,botBubble);input.value='';log.scrollTop=log.scrollHeight;input.focus()};o.querySelector('input').focus()}
function aboutContent(){return "<section><h3>What Mitra Work is</h3><p>Mitra Work is a shared work hub for small and growing teams. It brings task assignment, day-to-day progress, team communication, employee activity, and management reporting together in one workspace. The goal is to make it clear what needs doing, who owns it, what has changed, and where support is needed.</p></section>\n<section><h3>How a normal workday moves through the app</h3><ol><li>A manager assigns a task to an employee, with a due date, priority, instructions, project name, and optional attachment.</li><li>The employee opens the task, changes its status, and records a dated update with progress or blockers.</li><li>The employee adds a daily activity entry, keeping a short record of the work completed that day.</li><li>Managers review each person’s assigned work, activity, and status in Team, then use in-app messages or notes to share follow-ups.</li><li>Dashboard and Analytics summarize open, in-progress, and completed tasks so the team can see workload and progress.</li></ol><p>Employees can request task deletion when needed. The CEO reviews and approves or rejects that request, which keeps the final deletion decision with workspace leadership.</p></section>\n<section><h3>Workspace areas</h3><ul><li><strong>Dashboard:</strong> a role-aware overview of task progress, recent activity, and updates due. Employees also see their assigned work and personal daily activity.</li><li><strong>Tasks:</strong> task details, owners, due dates, priority, status, instructions, attachments, and dated task history.</li><li><strong>Messages:</strong> private in-app messages between active workspace members, with Inbox and Sent views.</li><li><strong>Analytics:</strong> a team-wide task count for administrators and a personal task count for employees, grouped by status and owner where applicable.</li><li><strong>Team:</strong> administrator views of employee profiles, account status, role, task activity, daily updates, notes, projects, and monthly work reports.</li><li><strong>Profile and settings:</strong> personal profile details such as name, job title, department, phone, professional summary, skills, and profile photo.</li><li><strong>Help:</strong> an in-app feature guide that answers common questions about the workspace.</li></ul></section>\n<section><h3>Roles and access</h3><p>The CEO account is the first administrator account. Team leaders, managers, and general managers have management access to team records and assigned work. Employees can see and update their own tasks, daily activity, messages, and profile. Server-side checks protect management actions and personal records; the interface also adapts its navigation to the signed-in role.</p></section>\n<section><h3>Technology and data storage</h3><p>The browser experience is built with HTML, CSS, and JavaScript. A Node.js server serves the web app and its API. Passwords are stored as scrypt hashes, and signed-in sessions use HTTP-only cookies. In local development, workspace records are kept in SQLite through the libSQL client, and uploaded files are stored under the local data directory.</p><p>For deployment on Vercel, the project is configured to use Turso for persistent SQLite-compatible database storage and private Vercel Blob storage for task attachments. The deployed workspace starts with no CEO account; its first administrator is created through the setup page.</p></section>\n<section><h3>Current capabilities and limits</h3><p>The current project supports task status and history, daily activity, private planning and personal notes, employee notes, team messages, employee roles, team workbooks, and task attachments. Password reset is not wired to an email delivery service yet. The Help assistant uses the app’s built-in feature guide; it does not currently connect to a hosted language model.</p></section>\n<section><h3>Future work</h3><p>Useful next steps include verified email-based password reset, rate limiting and stronger sign-in protections, CSRF defenses, audited role changes, automated database backups with restore drills, operational monitoring, and a security review before the app is used for sensitive information. Product improvements could add richer workload charts and filters, calendar and notification integrations, configurable approval rules, and an AI assistant connected to an approved language model so it can answer open-ended questions from up-to-date workspace documentation. These are future ideas, not features available today.</p></section>\n<section><h3>Contact and project inquiries</h3><p>For development, purchase, or project inquiries, email: <strong><a class=\"contact-email\" href=\"mailto:Shubhamkanpura7@gmail.com\">Shubhamkanpura7@gmail.com</a></strong></p></section>\r\n"}
function renderAboutPage(){document.querySelector('#page-content').innerHTML='<div class="page-heading"><div><div class="eyebrow">ABOUT THIS WORKSPACE</div><h1>About Mitra Work</h1><p>How this workspace works, what it uses, and what could come next.</p></div></div><article class="card about-page-content">'+aboutContent()+'</article>'}
function renderHelpPage(){document.querySelector('#page-content').innerHTML='<div class="page-heading"><div><div class="eyebrow">WORKSPACE / SUPPORT</div><h1>Help</h1><p>Ask questions about tasks, activity, team tools, analytics, and account access.</p></div><button class="primary" id="open-help-chat">Open help assistant</button></div><section class="card help-page-card"><h2>What can I ask?</h2><p>Try questions such as “How do I update a task?”, “Where can I see employee reports?”, or “What does Analytics show?” The assistant uses the app’s built-in feature guide.</p><div class="help-suggestions"><button class="secondary" data-help-question="How do I update a task?">Updating a task</button><button class="secondary" data-help-question="What can managers see in Team?">Team tools</button><button class="secondary" data-help-question="What does Analytics show?">Analytics</button></div></section>';document.querySelector('#open-help-chat').onclick=openHelpAssistant;document.querySelectorAll('[data-help-question]').forEach(b=>b.onclick=()=>{openHelpAssistant();setTimeout(()=>{const input=document.querySelector('#help-chat-form input');if(input){input.value=b.dataset.helpQuestion;input.focus()}},0)})}
function openAbout(){const o=document.createElement('div');o.className='overlay';o.innerHTML='<section class="modal about-modal" role="dialog" aria-modal="true" aria-labelledby="about-title"><div class="modal-head"><div><div class="eyebrow">ABOUT THIS WORKSPACE</div><h2 id="about-title">About Mitra Work</h2></div><button class="close" aria-label="Close">×</button></div><div class="about-content">'+aboutContent()+'</div><div class="form-footer"><button class="primary close-about">Close</button></div></section>';document.body.append(o);o.querySelector('.close').onclick=o.querySelector('.close-about').onclick=()=>o.remove();o.onclick=e=>{if(e.target===o)o.remove()}}

async function dashboard(){const d=await api(`/dashboard?date=${localDate()}`),p=d.taskProgress||{open:0,inProgress:0,completed:0},items=[['Open tasks',p.open,'☐'],['In progress',p.inProgress,'◷'],['Completed',p.completed,'✓']];if(d.employees!==undefined)items.push(['Team members',d.employees,'♧']);else items.push(['My projects',d.projects||0,'▦']);if(me.role==='ceo'&&d.pendingDeletes)items.push(['Delete approvals',d.pendingDeletes,'!']);const reportMonth=localDate().slice(0,7),teamBlocks=canAdmin()?`<div class="section-grid"><section class="card"><div class="card-title"><div><h3>Daily updates due</h3><small>Employees with assigned tasks who have not submitted today's update</small></div><span class="badge orange">${d.missingUpdates?.length||0}</span></div>${d.missingUpdates?.length?`<div class="table-wrap"><table class="data-table"><thead><tr><th>Employee</th><th>Open</th><th>In progress</th><th>Completed</th><th>Action</th></tr></thead><tbody>${d.missingUpdates.map(x=>`<tr><td>${esc(x.name)}</td><td>${x.open_tasks||0}</td><td>${x.in_progress_tasks||0}</td><td>${x.completed_tasks||0}</td><td><button class="secondary" onclick="goto('/employees/${x.id}')">View</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Everyone with assigned tasks has submitted today.</div>'}</section><section class="card"><div class="card-title"><div><h3>Team members</h3><small>${d.employees} active employees · task counts per person</small></div><button class="secondary" onclick="goto('/employees')">Open team</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Employee</th><th>Open</th><th>In progress</th><th>Completed</th></tr></thead><tbody>${(d.team||[]).map(x=>`<tr><td><button class="task-title-link" onclick="goto('/employees/${x.id}')">${esc(x.name)}</button><small>${esc(x.role.replaceAll('_',' '))}</small></td><td>${x.open_tasks||0}</td><td>${x.in_progress_tasks||0}</td><td>${x.completed_tasks||0}</td></tr>`).join('')}</tbody></table></div><div class="form-footer"><label>Month <input id="team-export-month" type="month" value="${reportMonth}"></label><button class="primary" onclick="downloadWorkReport()">Download team Excel workbook</button></div></section></div>`:'';const reminder=d.dailyReminder?`<div class="notice daily-reminder"><strong>Daily update needed</strong><span>Log today's work so your manager can see what you completed.</span><button class="secondary" onclick="document.querySelector('#daily-activity')?.scrollIntoView({behavior:'smooth'})">Update now</button></div>`:'';document.querySelector('#page-content').innerHTML=`<div class="page-heading"><div><div class="eyebrow">MITRA WORK / OVERVIEW</div><h1>Welcome back, ${esc(me.name.split(' ')[0])}</h1><p>See assigned work, daily progress, and team updates.</p></div><div class="dashboard-ctas"><button class="primary" onclick="openModal('tasks')">＋ Assign task</button><button class="secondary" onclick="goto('/messages')">✉ Send message</button></div></div>${reminder}<div class="cards">${items.map(x=>`<div class="card"><div class="stat"><div><small>${x[0]}</small><strong>${x[1]}</strong><div class="trend">Current workload</div></div><span class="stat-icon">${x[2]}</span></div></div>`).join('')}</div><div class="section-grid"><section class="card task-snapshot"><div class="card-title"><div><h3>Task progress</h3><small>Current work by status</small></div><button class="secondary" onclick="goto('/tasks')">View tasks</button></div><div class="progress-row"><span>Open</span><div class="progress-track"><i style="width:${d.totalTasks?p.open/d.totalTasks*100:0}%"></i></div><strong>${p.open}</strong></div><div class="progress-row"><span>In progress</span><div class="progress-track"><i class="in-progress" style="width:${d.totalTasks?p.inProgress/d.totalTasks*100:0}%"></i></div><strong>${p.inProgress}</strong></div><div class="progress-row"><span>Completed</span><div class="progress-track"><i class="completed" style="width:${d.totalTasks?p.completed/d.totalTasks*100:0}%"></i></div><strong>${p.completed}</strong></div></section><section class="card"><div class="card-title"><div><h3>Recent activity</h3><small>Team updates</small></div></div><div class="activity">${d.recent.length?d.recent.map((x,i)=>`<div class="activity-row"><span class="activity-dot">${['✓','◷','✉','↗'][i%4]}</span><div><strong>${esc(x.message)}</strong><small>${x.employee_id?`<a class="activity-person-link" href="/employees/${x.employee_id}" onclick="event.preventDefault();goto('/employees/${x.employee_id}')">${esc(x.employee_name||'Team member')}</a>`:'Workspace update'}</small></div><time>${new Date(x.created_at+'Z').toLocaleDateString()}</time></div>`).join(''):'<div class="empty">Team activity will appear here.</div>'}</div></section></div>${teamBlocks}`;}
